func largestRectangleArea(_ heights: [Int]) -> Int {
    let h = heights + [0]
    var stack: [Int] = [], best = 0
    for i in h.indices {
        while let top = stack.last, h[top] > h[i] {
            stack.removeLast()
            let left = stack.last ?? -1
            best = max(best, h[top] * (i - left - 1))
        }
        stack.append(i)
    }
    return best
}
